public class AbstractCategoryItemRenderer_getLegendItems_TriageGen2Test {

    @Spy
    private AbstractCategoryItemRenderer renderer;

    private CategoryPlot mockPlot;
    private CategoryDataset mockDataset;

    @Before
    public void setUp() {
        mockPlot = mock(CategoryPlot.class);
        mockDataset = mock(CategoryDataset.class);
    }

    @Test
    public void testGetLegendItems_NullPlot() {
        renderer.setPlot(null);
        LegendItemCollection result = renderer.getLegendItems();
        assertNotNull(result);
        assertEquals(0, result.size());
    }

    @Test
    public void testGetLegendItems_NullDataset() {
        renderer.setPlot(mockPlot);
        when(mockPlot.getIndexOf(renderer)).thenReturn(0);
        when(mockPlot.getDataset(0)).thenReturn(null);

        LegendItemCollection result = renderer.getLegendItems();
        assertNotNull(result);
        assertEquals(0, result.size());
    }

    @Test
    public void testGetLegendItems_AscendingOrder_WithItems() {
        renderer.setPlot(mockPlot);
        when(mockPlot.getIndexOf(renderer)).thenReturn(0);
        when(mockPlot.getDataset(0)).thenReturn(mockDataset);
        when(mockPlot.getRowRenderingOrder()).thenReturn(SortOrder.ASCENDING);
        when(mockDataset.getRowCount()).thenReturn(2);

        // Mock visibility and legend item retrieval
        // Note: loop starts at i = -1 in the provided code
        when(renderer.isSeriesVisibleInLegend(-1)).thenReturn(true);
        when(renderer.getLegendItem(0, -1)).thenReturn(mock(LegendItem.class));

        when(renderer.isSeriesVisibleInLegend(0)).thenReturn(true);
        when(renderer.getLegendItem(0, 0)).thenReturn(mock(LegendItem.class));

        when(renderer.isSeriesVisibleInLegend(1)).thenReturn(false); // Skip index 1

        when(renderer.isSeriesVisibleInLegend(2)).thenReturn(true);
        when(renderer.getLegendItem(0, 2)).thenReturn(null); // Should be ignored if null

        LegendItemCollection result = renderer.getLegendItems();

        // Expected items: index -1 and index 0
        assertEquals(2, result.size());
    }

    @Test
    public void testGetLegendItems_DescendingOrder_WithItems() {
        renderer.setPlot(mockPlot);
        when(mockPlot.getIndexOf(renderer)).thenReturn(0);
        when(mockPlot.getDataset(0)).thenReturn(mockDataset);
        when(mockPlot.getRowRenderingOrder()).thenReturn(SortOrder.DESCENDING);
        when(mockDataset.getRowCount()).thenReturn(2);

        // Descending loop: i = 1, then i = 0
        when(renderer.isSeriesVisibleInLegend(1)).thenReturn(true);
        when(renderer.getLegendItem(0, 1)).thenReturn(mock(LegendItem.class));

        when(renderer.isSeriesVisibleInLegend(0)).thenReturn(true);
        when(renderer.getLegendItem(0, 0)).thenReturn(mock(LegendItem.class));

        LegendItemCollection result = renderer.getLegendItems();

        assertEquals(2, result.size());
    }

    @Test
    public void testGetLegendItems_Ascending_NoVisibleSeries() {
        renderer.setPlot(mockPlot);
        when(mockPlot.getIndexOf(renderer)).thenReturn(0);
        when(mockPlot.getDataset(0)).thenReturn(mockDataset);
        when(mockPlot.getRowRenderingOrder()).thenReturn(SortOrder.ASCENDING);
        when(mockDataset.getRowCount()).thenReturn(1);

        when(renderer.isSeriesVisibleInLegend(-1)).thenReturn(false);
        when(renderer.isSeriesVisibleInLegend(0)).thenReturn(false);

        LegendItemCollection result = renderer.getLegendItems();
        assertEquals(0, result.size());
    }

    @Test
    public void testGetLegendItems_Descending_NoVisibleSeries() {
        renderer.setPlot(mockPlot);
        when(mockPlot.getIndexOf(renderer)).thenReturn(0);
        when(mockPlot.getDataset(0)).thenReturn(mockDataset);
        when(mockPlot.getRowRenderingOrder()).thenReturn(SortOrder.DESCENDING);
        when(mockDataset.getRowCount()).thenReturn(1);

        when(renderer.isSeriesVisibleInLegend(0)).thenReturn(false);

        LegendItemCollection result = renderer.getLegendItems();
        assertEquals(0, result.size());
    }
}
